 30→function CameraView({ onResult, onError }: { onResult: (animal: AnimalResult) => void; onError: () => void }) {
 31→    const videoRef = useRef<HTMLVideoElement>(null);
 32→    const streamRef = useRef<MediaStream | null>(null);
 33→    const [torch, setTorch] = useState(false);
 34→    const [hasTorch, setHasTorch] = useState(false);
 35→    const [scanning, setScanning] = useState(false);
 36→
 37→    const startCamera = useCallback(async () => {
 38→        try {
 39→            const stream = await navigator.mediaDevices.getUserMedia({
 40→                video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
 41→            });
 42→            streamRef.current = stream;
 43→            if (videoRef.current) {
 44→                videoRef.current.srcObject = stream;
 45→            }
 46→            const track = stream.getVideoTracks()[0];
 47→            const caps = track.getCapabilities?.() as MediaTrackCapabilities & { torch?: boolean };
 48→            if (caps?.torch) setHasTorch(true);
 49→        } catch {
 50→            onError();
 51→        }
 52→    }, [onError]);
 53→
 54→    useEffect(() => {
 55→        startCamera();
 56→        return () => {
 57→            streamRef.current?.getTracks().forEach((t) => t.stop());
 58→        };
 59→    }, [startCamera]);
 60→
 61→    const toggleTorch = async () => {
 62→        const track = streamRef.current?.getVideoTracks()[0];
 63→        if (track) {
 64→            await track.applyConstraints({ advanced: [{ torch: !torch } as MediaTrackConstraintSet] });
 65→            setTorch(!torch);
 66→        }
 67→    };
 68→
 69→    const simulateScan = async () => {
 70→        setScanning(true);
 71→        await new Promise((r) => setTimeout(r, 1000 + Math.random() * 1000));
 72→
 73→        if (Math.random() > 0.1) {
 74→            try {
 75→                const res = await fetch('/api/animals/random-crotal');
 76→                if (res.ok) {
 77→                    const animal = await res.json();
 78→                    onResult(animal);
 79→                    return;
 80→                }
 81→            } catch { /* fall through */ }
 82→        }
 83→        setScanning(false);
 84→        onError();
 85→    };
 86→
 87→    useEffect(() => {
 88→        if (!scanning) {
 89→            const timer = setTimeout(simulateScan, 2000);
 90→            return () => clearTimeout(timer);
 91→        }
 92→    }, [scanning]);
 93→
 94→    return (
 95→        <div className="relative h-full w-full bg-[#1A1A1A]">
 96→            <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-cover" />
 97→
 98→            <div className="absolute inset-0 flex items-center justify-center">
 99→                <div className="relative h-48 w-72">
100→                    <div className="absolute inset-0 border-2 border-white/60" />
101→                    {scanning && (
102→                        <div className="absolute inset-x-0 top-0 h-0.5 animate-bounce bg-[#E53935]" />
103→                    )}
104→                </div>
105→            </div>
106→
107→            <div className="absolute inset-x-0 top-8 text-center">
108→                <p className="text-sm font-medium text-white/90">
109→                    {scanning ? 'Buscando crotal...' : 'Enfoca el crotal del animal'}
110→                </p>
111→            </div>
112→
113→            <div className="absolute inset-x-0 bottom-8 flex items-center justify-center gap-8">
114→                {hasTorch && (
115→                    <button onClick={toggleTorch} className="flex size-12 items-center justify-center bg-white/20 text-white">
116→                        {torch ? <Flashlight className="size-5" /> : <FlashlightOff className="size-5" />}
117→                    </button>
118→                )}
119→            </div>
120→        </div>
121→    );
122→}
