206→function ManualInput({ onResult }: { onResult: (animal: AnimalResult) => void }) {
207→    const [code, setCode] = useState('ES');
208→    const [loading, setLoading] = useState(false);
209→    const [error, setError] = useState('');
210→
211→    const search = async () => {
212→        setError('');
213→        setLoading(true);
214→        try {
215→            const res = await fetch(`/api/animals/by-crotal/${code}`);
216→            if (res.ok) {
217→                onResult(await res.json());
218→            } else {
219→                setError('Animal no encontrado');
220→            }
221→        } catch {
222→            setError('Error de conexión');
223→        }
224→        setLoading(false);
225→    };
226→
227→    return (
228→        <div className="flex flex-col gap-5 p-6">
229→            <h2 className="text-2xl font-bold">Introducir código</h2>
230→            <p className="text-sm text-[#757575]">Escribe el código del crotal (formato: ES + 13 dígitos)</p>
231→            <div className="flex gap-2">
232→                <input
233→                    type="text"
234→                    value={code}
235→                    onChange={(e) => setCode(e.target.value.toUpperCase())}
236→                    placeholder="ES0480123000101"
237→                    className="h-[52px] flex-1 bg-[#F5F5F5] px-[18px] text-sm font-medium"
238→                    maxLength={15}
239→                />
240→                <button
241→                    onClick={search}
242→                    disabled={code.length < 10 || loading}
243→                    className="flex h-[52px] w-[52px] items-center justify-center bg-[#E53935] text-white disabled:opacity-50"
244→                >
245→                    <Search className="size-5" />
246→                </button>
247→            </div>
248→            {error && <p className="text-sm font-medium text-[#E53935]">{error}</p>}
249→        </div>
250→    );
251→}
