253→function PermissionDenied({ onManual }: { onManual: () => void }) {
254→    return (
255→        <div className="flex flex-col items-center gap-5 p-6 pt-16">
256→            <Camera className="size-16 text-[#757575]" />
257→            <h2 className="text-xl font-bold">Acceso a cámara denegado</h2>
258→            <div className="flex flex-col gap-2 text-sm text-[#757575]">
259→                <p className="font-semibold text-black">Para habilitar la cámara:</p>
260→                <p>iOS: Ajustes → Safari → Cámara → Permitir</p>
261→                <p>Android: Ajustes → Apps → Navegador → Permisos → Cámara</p>
262→            </div>
263→            <button onClick={onManual} className="w-full border-2 border-black py-[18px] text-center text-sm font-semibold">
264→                Introducir código manualmente
265→            </button>
266→        </div>
267→    );
268→}
