270→export default function ScannerIndex() {
271→    const [state, setState] = useState<ScannerState>('camera');
272→    const [animal, setAnimal] = useState<AnimalResult | null>(null);
273→
274→    const handleResult = (a: AnimalResult) => {
275→        setAnimal(a);
276→        setState('result');
277→    };
278→
279→    const handleError = () => setState('error');
280→    const handlePermissionDenied = () => setState('permission_denied');
281→
282→    return (
283→        <AppLayout breadcrumbs={breadcrumbs}>
284→            <Head title="Escanear Crotal" />
285→            <div className="flex h-full flex-col">
286→                {state === 'camera' && (
287→                    <div className="relative min-h-[500px] flex-1">
288→                        <CameraView onResult={handleResult} onError={() => { if (state === 'camera') handleError(); }} />
289→                    </div>
290→                )}
291→                {state === 'result' && animal && (
292→                    <AnimalResultCard animal={animal} onScanAgain={() => { setAnimal(null); setState('camera'); }} />
293→                )}
294→                {state === 'error' && (
295→                    <ErrorView onRetry={() => setState('camera')} onManual={() => setState('manual')} />
296→                )}
297→                {state === 'manual' && <ManualInput onResult={handleResult} />}
298→                {state === 'permission_denied' && <PermissionDenied onManual={() => setState('manual')} />}
299→
300→                {(state === 'camera') && (
301→                    <div className="flex items-center justify-center border-t-2 border-black bg-white p-4">
302→                        <button onClick={() => setState('manual')} className="text-sm font-semibold text-[#757575]">
303→                            Introducir código manualmente
304→                        </button>
305→                    </div>
306→                )}
307→            </div>
308→        </AppLayout>
309→    );
310→}
