    };
}

type ScannerState = 'instructions' | 'camera' | 'scanning' | 'result' | 'error' | 'manual' | 'permission_denied';

const breadcrumbs: BreadcrumbItem[] = [
    { title: 'Mi Explotación', href: '/dashboard' },
    { title: 'Escanear Crotal', href: '/scanner' },
